// GENERATED by app-studio-database-service (Supabase auth glue).
// Lives in src/custom/** — safe to edit; the generator never overwrites it.
import { getAccessToken, setSession } from '../gen/features/session';

const SUPABASE_URL = process.env.EXPO_PUBLIC_SUPABASE_URL ?? '';
const SUPABASE_ANON_KEY = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY ?? '';

// Ensures anonymous sign-in runs at most once even if several requests fire
// before the first one resolves.
let anonInFlight: Promise<string | null> | null = null;

/**
 * Guarantee an authenticated session. Supabase table RLS is `TO authenticated`
 * (auth.uid() = auth_user_id), so an unauthenticated caller sees no rows and
 * cannot write. If the user hasn't signed in (e.g. a CRUD-only app with no
 * login screen), bootstrap an ANONYMOUS Supabase session so CRUD works; each
 * anonymous user still only sees their own rows. Requires "Allow anonymous
 * sign-ins" enabled in the Supabase project. Returns null if it can't (the app
 * then behaves exactly as before — unauthenticated).
 */
async function ensureSession(): Promise<string | null> {
  const existing = getAccessToken();
  if (existing) return existing;
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) return null;
  if (!anonInFlight) {
    anonInFlight = (async () => {
      try {
        const res = await fetch(`${SUPABASE_URL}/auth/v1/signup`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            apikey: SUPABASE_ANON_KEY,
            Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
          },
          body: JSON.stringify({}),
        });
        if (!res.ok) return null;
        const data: any = await res.json();
        const access = data?.access_token;
        if (access) {
          await setSession(access, data?.refresh_token);
          return access as string;
        }
        return null;
      } catch {
        return null;
      } finally {
        anonInFlight = null;
      }
    })();
  }
  return anonInFlight;
}

/** Attached to every API request by src/gen/api/client.ts. */
export async function getAuthHeaders(): Promise<Record<string, string>> {
  const token = (await ensureSession()) ?? getAccessToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

/** Call after a successful sign-in/sign-up to store the session. */
export async function onLoginSuccess(resp: any): Promise<void> {
  const access = resp?.access_token;
  const refresh = resp?.refresh_token;
  if (access) await setSession(access, refresh);
}

/** Called by the API client's 401 interceptor.
 *  Token refresh is disabled for now (login + CRUD only) — a 401 means the
 *  user must sign in again, so we simply report "not refreshed". */
export async function refreshSession(): Promise<boolean> {
  return false;
}
